// ---- end reconstructed data ----

static int lastImageWidth;
static int lastImageHeight;
static int lastImageSize;
static const unsigned char* lastImageData;
static int OpenCloseRefCount;
static u8 ResetWasPaused;
static bool CanGetResetPauseState = true;

// PORT: Aurora's headers declare all of these, with real GX/VI types.
#if defined(PORT_USE_AURORA)
#include <dolphin/gx.h>
#include <dolphin/vi.h>
#else
extern "C"
{
    void GXDrawDone(void);
    void GXFlush(void);
    void GXCopyDisp(void*, unsigned char);
    void GXPokeColorUpdate(unsigned char);
    void GXPokeBlendMode(int, int, int, int);
    void GXPokeARGB(unsigned short, unsigned short, unsigned long);
    void VIWaitForRetrace(void);
    void VISetBlack(unsigned char);
    void VIFlush(void);
    void VISetNextFrameBuffer(void*);
}
#endif

void* glxGetDisplayedBuffer();
void* glxGetBackBuffer();
void glx_ClearXFB(void*);

static inline void UncompressLidMessage(const unsigned char* compressed, int compressedSize, unsigned char* uncompressed)
{
    int index = 0;
    int i = 0;

    while (i < (compressedSize - 1))
    {
        if (compressed[i] == 0)
        {
            int k = 0;
            while (k < compressed[i + 1])
            {
                uncompressed[index] = 0;
                index++;
                k++;
            }
            i++;
        }
        else
        {
            uncompressed[index] = compressed[i];
            index++;
        }
        i++;
    }

    uncompressed[index] = compressed[compressedSize - 1];
}

/**
 * Offset/Address/Size: 0x624 | 0x80094540 | size: 0x26C
 */
static void DisplayMessage(int imagewidth, int imageheight, const unsigned char* datastart, int datasize, unsigned long color, bool centered)
{
    unsigned int centeredFlag;
    int yStart;
    unsigned char* expanded;
    unsigned char* row;
    int yCenter;
    int yBottom;
    int rowBytes;
    void* fb;
    int pass;
    int xStart;
    int xEnd;
    int yEnd;
    int y;
    int x;

    GXDrawDone();
    VIWaitForRetrace();
    VISetBlack(1);
    VIFlush();
    VIWaitForRetrace();
    VIWaitForRetrace();

    lastImageWidth = imagewidth;
    lastImageHeight = imageheight;
    lastImageData = datastart;
    lastImageSize = datasize;

    expanded = (unsigned char*)nlMalloc((unsigned long)((imagewidth * imageheight) / 8), 0x20, 1);

    UncompressLidMessage(datastart, datasize, expanded);

    GXPokeColorUpdate(1);
    GXPokeBlendMode((GXBlendMode)0, (GXBlendFactor)1, (GXBlendFactor)0,
                    (GXLogicOp)0xF);

    const int xStartTemp = (0x280 - imagewidth) / 2;
    centeredFlag = ((unsigned char)centered == 0);
    pass = 0;
    yCenter = (0x1C0 - imageheight) / 2;
    xStart = xStartTemp;
    xEnd = xStartTemp + imagewidth;
    yBottom = 0x1A0 - imageheight;
    rowBytes = imagewidth / 8;

    while (pass < 4)
    {
        if ((pass == 0) || (pass == 2))
        {
            fb = glxGetDisplayedBuffer();
        }
        else
        {
            fb = glxGetBackBuffer();
        }

        glx_ClearXFB(fb);

        yStart = yBottom;
        if (centeredFlag != 0)
        {
            yStart = yCenter;
        }

        y = yStart;
        yEnd = yStart + imageheight;
        while (y < yEnd)
        {
            x = xStart;
            int rowOffset = rowBytes * (y - yStart);
            row = expanded + rowOffset;

            while (x < xEnd)
            {
                int pixel = x - xStart;
                if ((row[pixel / 8] & (1 << (pixel % 8))) != 0)
                {
                    GXPokeARGB((unsigned short)x, (unsigned short)y, color);
                }
                x++;
            }
            y++;
        }

        GXCopyDisp(fb, 1);
        GXDrawDone();
        GXFlush();
        pass++;
    }

    GXPokeColorUpdate(0);
    delete[] expanded;

    VIWaitForRetrace();
    VIWaitForRetrace();
    VISetBlack(0);
    VISetNextFrameBuffer(fb);
    VIFlush();
    VIWaitForRetrace();
}

/**
 * Offset/Address/Size: 0x278 | 0x80094194 | size: 0x3AC
 */
void DisplayDVDMessageSebring(int arg)
{
    int lang;
    AudioStreamTrack::TrackManagerBase* trackMgr;

    if (CanGetResetPauseState)
    {
        ResetWasPaused = ResetTask::s_resetPaused;
        CanGetResetPauseState = false;
    }

    ResetTask::s_resetPaused = 0;
    OpenCloseRefCount++;

    int region = *GetRegion();
    switch (region)
    {
    case 0:
        lang = 0;
        break;
    case 1:
        switch ((u8)OSGetLanguage())
        {
        case 1:
            lang = 2;
            break;
        case 2:
            lang = 1;
            break;
        case 3:
            lang = 3;
            break;
        case 4:
            lang = 4;
            break;
        default:
            lang = 6;
            break;
        }
        break;
    case 2:
        lang = 5;
        break;
    default:
        lang = g_Language;
        break;
    }

    if (lang > 6)
        lang = 0;

    switch (arg + 1)
    {
    case 5:
        DisplayMessage(LID_DATA[lang][0].x, LID_DATA[lang][0].y, LID_DATA[lang][0].text, LID_DATA[lang][0].param, (unsigned long)-1, false);
        break;
    case 6:
        DisplayMessage(LID_DATA[lang][1].x, LID_DATA[lang][1].y, LID_DATA[lang][1].text, LID_DATA[lang][1].param, (unsigned long)-1, false);
        break;
    case 0:
        DisplayMessage(LID_DATA[lang][2].x, LID_DATA[lang][2].y, LID_DATA[lang][2].text, LID_DATA[lang][2].param, (unsigned long)-1, false);
        break;
    case 12:
        DisplayMessage(LID_DATA[lang][3].x, LID_DATA[lang][3].y, LID_DATA[lang][3].text, LID_DATA[lang][3].param, (unsigned long)-1, false);
        break;
    case 7:
        DisplayMessage(LID_DATA[lang][4].x, LID_DATA[lang][4].y, LID_DATA[lang][4].text, LID_DATA[lang][4].param, (unsigned long)-1, false);
        break;
    }

    if (g_pGame != NULL)
    {
        TRANSITION_STATE transState = TransitionTask::sm_pGlobalTask != NULL
                                        ? TransitionTask::sm_pGlobalTask->m_TransitionState
                                        : eTS_Unknown;

        if (transState == eTS_InState)
        {
            PriorityStream* ps = Audio::GetPriorityStream();
            if (ps != NULL)
            {
                Audio::GetPriorityStream()->FakePause(0);
            }
            CrowdMood::Purge(true);

            if (nlTaskManager::m_pInstance->m_CurrState == 1)
            {
                trackMgr = g_pTrackManager;
                AudioStreamTrack::StreamTrack* track = trackMgr->GetTrack(nlStringLowerHash("Announcer"));
                if (track != NULL)
                {
                    track->Pause(0, false);
                }
            }
        }
        else
        {
            trackMgr = g_pTrackManager;
            AudioStreamTrack::StreamTrack* track = trackMgr->GetTrack(nlStringLowerHash("FE"));
            if (track != NULL)
            {
                track->Pause(0, false);
            }
        }

        if (g_pTrackManager != NULL)
        {
            // PORT: null when audio is disabled, nothing to command.
            if (g_pTrackManager != NULL) g_pTrackManager->StopAllTracks(0);
        }
        Audio::Silence();
    }
    else
    {
        trackMgr = g_pTrackManager;
        if (trackMgr != NULL)
        {
            AudioStreamTrack::StreamTrack* track = trackMgr->GetTrack(nlStringLowerHash("FE"));
            if (track != NULL)
            {
                track->Pause(0, false);
            }
            trackMgr = g_pTrackManager;
            track = trackMgr->GetTrack(nlStringLowerHash("FE2"));
            if (track != NULL)
            {
                track->Pause(0, false);
            }
        }
    }

    for (int i = 0; i < 4; i++)
    {
        cGlobalPad* pad = cPadManager::GetPad(i);
        if (pad != NULL)
        {
            StopRumbleAction(pad);
        }
    }

    ResetTask::s_checkCardRemoved = true;
}

/**
 * Offset/Address/Size: 0x58 | 0x80093F74 | size: 0x220
 */
void DVDAllClearSebring(int nStatus)
{
    AudioStreamTrack::TrackManagerBase* trackMgr;

    DisplayMessage(lastImageWidth, lastImageHeight, lastImageData, lastImageSize, 0, false);

    while (nlAsyncReadsPending(NULL))
    {
        nlServiceFileSystem();
    }

    if (g_pGame != NULL)
    {
        TRANSITION_STATE transState = TransitionTask::sm_pGlobalTask != NULL
                                        ? TransitionTask::sm_pGlobalTask->m_TransitionState
                                        : eTS_Unknown;

        if (transState == eTS_InState)
        {
            if (nlTaskManager::m_pInstance->m_CurrState != 1)
            {
                PriorityStream* ps = Audio::GetPriorityStream();
                if (ps != NULL)
                {
                    if (IsMoviePlayingInStrikers101())
                    {
                        Audio::GetPriorityStream()->m_Track.Stop(0);
                    }
                    else
                    {
                        Audio::GetPriorityStream()->FakeResume(false);
                    }
                }
                CrowdMood::RestartLoops();
                CrowdMood::SetCrowdVolume(0x7F, 0);
            }
            else
            {
                if (!IsMoviePlayingInStrikers101())
                {
                    trackMgr = g_pTrackManager;
                    AudioStreamTrack::StreamTrack* track = trackMgr->GetTrack(nlStringLowerHash("Announcer"));
                    if (track != NULL)
                    {
                        track->Resume();
                    }
                }
            }
        }
        else
        {
            trackMgr = g_pTrackManager;
            AudioStreamTrack::StreamTrack* track = trackMgr->GetTrack(nlStringLowerHash("FE"));
            if (track != NULL)
            {
                track->Resume();
            }
            trackMgr = g_pTrackManager;
            track = trackMgr->GetTrack(nlStringLowerHash("FE2"));
            if (track != NULL)
            {
                track->Resume();
            }
        }
    }
    else
    {
        trackMgr = g_pTrackManager;
        if (trackMgr != NULL)
        {
            AudioStreamTrack::StreamTrack* track = trackMgr->GetTrack(nlStringLowerHash("FE"));
            if (track != NULL)
            {
                track->Resume();
            }
            trackMgr = g_pTrackManager;
            track = trackMgr->GetTrack(nlStringLowerHash("FE2"));
            if (track != NULL)
            {
                track->Resume();
            }
        }
    }

    OpenCloseRefCount--;
    ResetTask::s_resetPaused = ResetWasPaused;
    CanGetResetPauseState = true;
    ResetTask::s_checkCardRemoved = false;
}

/**
 * Offset/Address/Size: 0x0 | 0x80093F1C | size: 0x58
 */
void DisplayLoadingMessageFast()
{
    int lang = g_Language;
    if (lang > 6)
    {
        lang = 0;
    }

    DisplayMessage(
        LOADING_TEXT_DATA[lang].x,
        LOADING_TEXT_DATA[lang].y,
        LOADING_TEXT_DATA[lang].text,
        LOADING_TEXT_DATA[lang].param,
        0xFFFFA800,
        true);
}
